package org.synqoria.scheduling;
import org.synqoria.security.TrustedAccessContext;import java.time.*;import java.util.*;
public class AppointmentScopedSearchTest{public static void main(String[]a){int n=0;var t=UUID.randomUUID();var f=UUID.randomUUID();var p=UUID.randomUUID();var r=UUID.randomUUID();var c=new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of("appointment:read"),Set.of(p));var rows=new ArrayList<AppointmentAggregate>();for(int i=3;i>=0;i--)rows.add(new AppointmentAggregate(UUID.randomUUID(),t,f,p,r,new AppointmentWindow(Instant.parse("2026-11-01T09:00:00Z").plusSeconds(i*3600),Instant.parse("2026-11-01T09:30:00Z").plusSeconds(i*3600),ZoneId.of("UTC")),AppointmentAggregate.State.CONFIRMED,1,null));rows.add(new AppointmentAggregate(UUID.randomUUID(),t,f,UUID.randomUUID(),r,rows.get(0).window(),AppointmentAggregate.State.CONFIRMED,1,null));rows.add(new AppointmentAggregate(UUID.randomUUID(),UUID.randomUUID(),f,p,r,rows.get(0).window(),AppointmentAggregate.State.CONFIRMED,1,null));var s=new AppointmentScopedSearch();var page=s.page(c,rows,0,2);check(page.items().size()==2);n++;check(page.hasMore());n++;check(page.items().get(0).window().start().isBefore(page.items().get(1).window().start()));n++;check(s.page(c,rows,2,2).items().size()==2);n++;check(!s.page(c,rows,2,2).hasMore());n++;check(s.page(null,rows,0,10).items().isEmpty());n++;check(s.page(new TrustedAccessContext(t,f,UUID.randomUUID(),Set.of(),Set.of(p)),rows,0,10).items().isEmpty());n++;check(s.page(c,rows,50,10).items().isEmpty());n++;try{s.page(c,rows,0,101);throw new AssertionError();}catch(IllegalArgumentException expected){n++;}System.out.println("PASS "+n+" scoped query assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
